method(update_parameters, Reduction) <- function(x, problem, ...) {
  invisible(NULL)
}

# -- Derivative chain-rule generics (Phase 4.4) -------------------
## CVXPY SOURCE: reduction.py:87-167.
##
## Used by Problem$backward() / Problem$derivative() to walk the
## solving chain.  Default behaviour is "no transformation":
##   * `param_backward` returns NULL (no contribution from this
##     reduction to this parameter's gradient).
##   * `param_forward`  returns NULL (no transformation of the
##     incoming delta).
##   * `var_backward` / `var_forward` return the value unchanged.
## Reductions that re-express variables or parameters override these.

#' Reduction chain-rule hooks (backward / forward, parameter / variable)
#'
#' @param x A `Reduction`.
#' @param param A `Parameter` from the original problem.
#' @param dparams Named list of param-id -> gradient arrays for the
#'   reduced (transformed) parameters.
#' @returns A gradient array for `param`, or `NULL` if this reduction
#'   does not touch `param`.
#' @name reduction-chain-rule
#' @export
param_backward <- new_generic("param_backward", c("x"),
  function(x, param, dparams) S7_dispatch())
method(param_backward, Reduction) <- function(x, param, dparams) NULL

#' @rdname reduction-chain-rule
#' @param delta Numeric array of perturbations to the original `param`.
#' @returns Named list of transformed-param-id -> delta arrays, or
#'   `NULL` if this reduction does not touch `param`.
#' @export
param_forward <- new_generic("param_forward", c("x"),
  function(x, param, delta) S7_dispatch())
method(param_forward, Reduction) <- function(x, param, delta) NULL

#' @rdname reduction-chain-rule
#' @param var A `Variable` from the original problem.
#' @param value Numeric array (gradient or delta) attached to `var`.
#' @export
var_backward <- new_generic("var_backward", c("x"),
  function(x, var, value) S7_dispatch())
method(var_backward, Reduction) <- function(x, var, value) value

#' @rdname reduction-chain-rule
#' @export
var_forward <- new_generic("var_forward", c("x"),
  function(x, var, value) S7_dispatch())
method(var_forward, Reduction) <- function(x, var, value) value

## reduce: convenience -- apply and cache result
## CVXPY SOURCE: reduction.py lines 169-192
reduction_reduce <- function(x, problem) {
  if (!is.null(x@.cache$emitted_problem)) {
    return(x@.cache$emitted_problem)
  }
  result <- reduction_apply(x, problem)
  x@.cache$emitted_problem <- result[[1L]]
  x@.cache$retrieval_data <- result[[2L]]
  result[[1L]]
}

## retrieve: convenience -- invert cached result
## CVXPY SOURCE: reduction.py lines 194-215
reduction_retrieve <- function(x, solution) {
  if (is.null(x@.cache$retrieval_data)) {
    cli_abort("{.fn reduction_reduce} must be called before {.fn reduction_retrieve}.")
  }
  reduction_invert(x, solution, x@.cache$retrieval_data)
}
